import { describe, it, expect, vi, afterEach } from 'vitest'
import type { RepairDetailWithCustomer } from '../types.js'

// ---------------------------------------------------------------------------
// Mock fetch globally
// ---------------------------------------------------------------------------

const mockFetch = vi.fn<any>()

Object.defineProperty(globalThis, 'fetch', {
  value: mockFetch,
  writable: true,
})

vi.mock('../api.js', async (importOriginal) => {
  const actual = await importOriginal()
  return actual
})

// Need to re-import after mocking fetch
async function importApi() {
  // Clear module cache so mocks take effect
  vi.resetModules()
  Object.defineProperty(globalThis, 'fetch', { value: mockFetch })
  const mod = await import('../api.js')
  return mod
}

function createMockRepair(id: string, status: RepairDetailWithCustomer['status'], plannedDate: number | null): RepairDetailWithCustomer {
  return {
    id,
    assignedTo: null,
    status,
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate,
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Test Customer',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane',
    bicycleColor: 'blue',
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('getRepairsForWeek', () => {
  afterEach(() => {
    vi.clearAllMocks()
  })

  it('calls the repairs endpoint with from, to, and statusIn params', async () => {
    const { getRepairsForWeek } = await importApi()

    const mockRepairs: RepairDetailWithCustomer[] = [
      createMockRepair('r1', 'in_progress', 1706832000000),
    ]

    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ repairs: mockRepairs, total: 1, page: 1, pageSize: 100, totalPages: 1 }),
    })

    const result = await getRepairsForWeek(1706745600000, 1707350400000)

    // Verify the call was made with correct params (URLSearchParams encodes commas as %2C)
    const [calledUrl] = mockFetch.mock.calls[0]
    expect(calledUrl).toContain('from=1706745600000')
    expect(calledUrl).toContain('to=1707350400000')
    // statusIn commas are URL-encoded as %2C
    expect(calledUrl).toContain('statusIn=in_progress%2Con_hold%2Cverified%2Cready')
    expect(calledUrl).toContain('page=1')
    expect(calledUrl).toContain('pageSize=100')
    expect(result.repairs).toHaveLength(1)
    expect(result.repairs[0].id).toBe('r1')
  })

  it('throws when the API response is not ok', async () => {
    const { getRepairsForWeek } = await importApi()

    mockFetch.mockResolvedValueOnce({
      ok: false,
      status: 500,
    })

    await expect(getRepairsForWeek(1706745600000, 1707350400000)).rejects.toThrow('Failed to fetch repairs for week')
  })
})

/**
 * Repair List Page
 *
 * Shows all active repairs with status color-coding, customer name, bicycle info,
 * assigned worker, planned date, and pickup date. Managers can filter by status,
 * assigned worker, and pickup date (today/this week). Default sorting is by
 * planned_date descending (most urgent first).
 */

import { useState, useEffect, useCallback, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Calendar,
  ChevronDown,
  Plus,
  User,
  Wrench,
} from 'lucide-react'
