    const result = getDateAnchor({ plannedDate, createdAt })
    expect(typeof result).toBe('number')
    expect(result).toBe(plannedDate)
  })
})

/**
 * useRepairDetailCache — Unit tests.
 *
 * Verifies the three states required by the slice:
 *   - cache miss: first call to loadDetail triggers a single GET /api/repairs/:id
 *   - cache hit:  subsequent calls for the same id do NOT re-fetch
 *   - retry:      a failed load leaves the cache empty and exposes the error;
 *                 a subsequent call to loadDetail re-fetches
 */

import { describe, it, expect, vi, afterEach } from 'vitest'
import { renderHook, act, waitFor } from '@testing-library/react'
import type { RepairDetailResponse } from '../../api.js'

// ---------------------------------------------------------------------------
// Mock the API module — must be hoisted to top of file for vi.mock
// ---------------------------------------------------------------------------

const mockGetRepair = vi.fn() as ReturnType<typeof vi.fn> & {
  mockResolvedValueOnce: (value: RepairDetailResponse) => void
  mockRejectedValueOnce: (error: Error) => void
}

vi.mock('../../api.js', () => ({
  getRepair: (...args: unknown[]) => mockGetRepair(...args),
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function makeDetail(id: string): RepairDetailResponse {
  return {
    repair: {
      id,
      bicycleId: 'b1',
      assignedTo: 'u1',
      status: 'in_progress',
      customerNotes: null,
      internalNotes: null,
      holdReason: null,
      holdReasonNote: null,
      plannedDate: 1706832000000,
      pickupDate: 1707004800000,
      completedAt: null,
      createdAt: 1706745600000,
    },
    customer: {
      id: 'c1',
      firstName: 'Alice',
      lastName: 'Doe',
      companyName: null,
      phone: '+32 470 12 34 56',
      email: 'alice@example.com',
    },
    bicycle: {
      id: 'b1',
      brand: 'Trek',
      model: 'Domane',
      color: 'blue',
      year: 2022,
    },
    lineItems: [],
    workLogs: [],
  }
}

// Need to import the hook after vi.mock is hoisted
import { useRepairDetailCache } from '../useRepairDetailCache.js'

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('useRepairDetailCache', () => {
  afterEach(() => {
    vi.resetAllMocks()
  })

  // -- Cache miss / hit -------------------------------------------------

  it('fetches on first load (cache miss) and reuses on second call (cache hit)', async () => {
    const detail = makeDetail('r1')
    mockGetRepair.mockResolvedValueOnce(detail)

    const { result } = renderHook(() => useRepairDetailCache())

    // Initial state — no cache, no error, nothing loading
    expect(result.current.detailCache.size).toBe(0)
    expect(result.current.detailLoading.size).toBe(0)
    expect(result.current.detailError).toBeNull()

    // First call — should fetch
    let firstResult: RepairDetailResponse | null = null
    await act(async () => {
      firstResult = await result.current.loadDetail('r1')
    })
    expect(firstResult).toEqual(detail)
    expect(mockGetRepair).toHaveBeenCalledTimes(1)
    expect(mockGetRepair).toHaveBeenCalledWith('r1')
    expect(result.current.detailCache.get('r1')).toEqual(detail)
    expect(result.current.detailLoading.size).toBe(0)
    expect(result.current.detailError).toBeNull()

    // Second call — should hit the cache and NOT re-fetch
    let secondResult: RepairDetailResponse | null = null
    await act(async () => {
      secondResult = await result.current.loadDetail('r1')
    })
    expect(secondResult).toEqual(detail)
    expect(mockGetRepair).toHaveBeenCalledTimes(1) // still 1, no re-fetch
  })

  it('tracks loading state during in-flight request', async () => {
    let resolveFetch: ((value: RepairDetailResponse) => void) | undefined
    const pending = new Promise<RepairDetailResponse>((resolve) => {
      resolveFetch = resolve
    })
    mockGetRepair.mockReturnValueOnce(pending)

    const { result } = renderHook(() => useRepairDetailCache())

    // Kick off the fetch
    act(() => {
      void result.current.loadDetail('r2')
    })

    // While in flight: id is in the loading set
    await waitFor(() => {
      expect(result.current.detailLoading.has('r2')).toBe(true)
    })

    // Resolve the fetch
    await act(async () => {
      resolveFetch?.(makeDetail('r2'))
      await pending
    })

    await waitFor(() => {
      expect(result.current.detailLoading.has('r2')).toBe(false)
    })
    expect(result.current.detailCache.get('r2')).toBeDefined()
  })

  it('does not double-fetch when loadDetail is called while a request is in flight', async () => {
    let resolveFetch: ((value: RepairDetailResponse) => void) | undefined
    const pending = new Promise<RepairDetailResponse>((resolve) => {
      resolveFetch = resolve
    })
    mockGetRepair.mockReturnValueOnce(pending)

    const { result } = renderHook(() => useRepairDetailCache())

    // Kick off the first call
    act(() => {
      void result.current.loadDetail('r3')
    })

    // Second call while in flight — should be a no-op (returns null)
    let concurrent: RepairDetailResponse | null = null
    await act(async () => {
      concurrent = await result.current.loadDetail('r3')
    })
    expect(concurrent).toBeNull()
    expect(mockGetRepair).toHaveBeenCalledTimes(1)

    // Resolve the in-flight request
    await act(async () => {
      resolveFetch?.(makeDetail('r3'))
      await pending
    })
  })

  // -- Error + retry ----------------------------------------------------

  it('exposes error on failure and re-fetches on retry', async () => {
    const fetchError = new Error('Network down')
    mockGetRepair.mockRejectedValueOnce(fetchError)
    const detail = makeDetail('r4')
    mockGetRepair.mockResolvedValueOnce(detail)

    const { result } = renderHook(() => useRepairDetailCache())

    // First call — fails
    let failed: RepairDetailResponse | null = null
    await act(async () => {
      failed = await result.current.loadDetail('r4')
    })
    expect(failed).toBeNull()
    expect(result.current.detailError).toBe('Network down')
    expect(result.current.detailCache.has('r4')).toBe(false)
    expect(result.current.detailLoading.size).toBe(0)
    expect(mockGetRepair).toHaveBeenCalledTimes(1)

    // Retry — should clear error and re-fetch
    let retried: RepairDetailResponse | null = null
    await act(async () => {
      retried = await result.current.loadDetail('r4')
    })
    expect(retried).toEqual(detail)
    expect(mockGetRepair).toHaveBeenCalledTimes(2)
    expect(result.current.detailError).toBeNull()
    expect(result.current.detailCache.get('r4')).toEqual(detail)
  })

  it('uses a generic error message when the thrown value is not an Error', async () => {
    mockGetRepair.mockRejectedValueOnce('string-error')
    const { result } = renderHook(() => useRepairDetailCache())

    await act(async () => {
      await result.current.loadDetail('r5')
    })
    expect(result.current.detailError).toBe('Failed to load repair')
  })
})

