async function fetchRepair(id: string): Promise<RepairDetailResponse> {
  const response = await fetch(`/api/repairs/${id}`)
  if (!response.ok) {
    throw new Error('Failed to fetch repair')
  }
  return response.json()
}

/** Search parts catalog by name (case-insensitive partial match) */
async function searchParts(query: string): Promise<PartCatalogItem[]> {
  const response = await fetch(`/api/parts?search=${encodeURIComponent(query)}`)
  if (!response.ok) return []
  const data = await response.json()
  return data.parts ?? []
}

/** Fetch all active labor services */
async function fetchLaborServices(): Promise<LaborServiceOption[]> {
  const response = await fetch('/api/repairs/labor-services')
  if (!response.ok) return []
  const data = await response.json()
  return data.laborServices ?? []
}

// ---------------------------------------------------------------------------
// Helpers — format values for display
// ---------------------------------------------------------------------------

function formatDate(epochMs: number | null): string {
  if (!epochMs) return '—'
  const d = new Date(epochMs)
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
}

function formatTime(epochMs: number | null): string {
  if (!epochMs) return '—'
  const d = new Date(epochMs)
  return d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })
}

function formatCurrency(cents: number): string {
  return `${(cents / 100).toFixed(2)} EUR`
}

function formatDuration(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000)
  const hours = Math.floor(totalSeconds / 3600)
  const minutes = Math.floor((totalSeconds % 3600) / 60)
  const seconds = totalSeconds % 60

  if (hours > 0) {
    return `${hours}h ${minutes}m`
  }
  if (minutes > 0) {
    return `${minutes}m ${seconds}s`
  }
  return `${seconds}s`
}

function formatElapsed(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000)
  const hours = Math.floor(totalSeconds / 3600)
  const minutes = Math.floor((totalSeconds % 3600) / 60)
  const seconds = totalSeconds % 60

  if (hours > 0) {
    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
  }
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
}

function getCustomerName(customer?: CustomerInfo): string {
  if (!customer) return '—'
  const parts = [customer.firstName, customer.lastName].filter(Boolean)
  return parts.join(' ') || customer.companyName || '—'
}

/** Look up worker display name and role from the workers list */
function getWorkerDisplay(
  workerId: string | null,
  workersList: WorkerOption[]
): { name: string; role: string } {
  if (!workerId) return { name: 'Unassigned', role: '' }
  const worker = workersList.find((w) => w.id === workerId)
  if (!worker) return { name: workerId.slice(0, 8), role: '' }
  return { name: worker.name, role: worker.role }
}

