/**
 * RepairCard — Component tests.
 *
 * Verifies:
 * - Renders customer name, bicycle model, status badge, assigned worker
 * - Status badge uses STATUS_COLORS mapping
 * - Card body click navigates to repair detail page
 * - Pickup day indicator shown when pickupDate is set
 * - Pickup day indicator hidden when pickupDate is null
 */

import { describe, it, expect } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import type { RepairDetailWithCustomer } from '../../types.js'
import { RepairCard } from '../RepairCard.js'

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createRepair(overrides?: Partial<RepairDetailWithCustomer>): RepairDetailWithCustomer {
  return {
    id: 'repair-001',
    assignedTo: null,
    status: 'in_progress',
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate: 1706832000000, // Feb 2, 2024
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Jane Doe',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane SL',
    bicycleColor: 'blue',
    ...overrides,
  }
}

function renderCard(repair?: RepairDetailWithCustomer) {
  const r = repair ?? createRepair()
  return render(
    <MemoryRouter>
      <RepairCard repair={r} workers={[]} />
    </MemoryRouter>
  )
}

// ---------------------------------------------------------------------------
// Tests: Basic rendering
// ---------------------------------------------------------------------------

describe('RepairCard — basic rendering', () => {
  it('renders customer name', () => {
    renderCard()
    expect(screen.getByText('Jane Doe')).toBeInTheDocument()
  })

  it('renders bicycle brand and model', () => {
    renderCard()
    expect(screen.getByText(/Trek Domane SL/)).toBeInTheDocument()
  })

  it('renders status badge with correct text', () => {
    renderCard()
    expect(screen.getByText(/in progress/i)).toBeInTheDocument()
  })

  it('renders assigned worker name when assignedTo is set and workers provided', () => {
    const repair = createRepair({ assignedTo: 'worker-01' })
    render(
      <MemoryRouter>
        <RepairCard repair={repair} workers={[{ id: 'worker-01', name: 'Bob Smith' }]} />
      </MemoryRouter>
    )
    expect(screen.getByText('Bob Smith')).toBeInTheDocument()
  })

  it('renders "Unassigned" when assignedTo is null', () => {
    renderCard()
    expect(screen.getByText('Unassigned')).toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: Status badge colors
// ---------------------------------------------------------------------------

describe('RepairCard — status badge colors', () => {
  it.each([
    ['intake', 'blue'],
    ['in_progress', 'yellow'],
    ['on_hold', 'orange'],
    ['verified', 'purple'],
    ['ready', 'green'],
  ] as [RepairDetailWithCustomer['status'], string][])(
    'applies %s status color for "%s"',
    (status, expectedColor) => {
      const repair = createRepair({ status })
      renderCard(repair)
      // Check that the badge element contains the expected color class
      const badge = screen.getByText(new RegExp(status.replace('_', ' '), 'i'))
      expect(badge.className).toContain(expectedColor)
    }
  )
})

// ---------------------------------------------------------------------------
// Tests: Card click navigation
// ---------------------------------------------------------------------------

describe('RepairCard — click navigation', () => {
  it('navigates to repair detail page when card body is clicked', async () => {
    render(
      <MemoryRouter initialEntries={['/repairs']}>
        <RepairCard repair={createRepair()} workers={[]} />
      </MemoryRouter>
    )
    const card = screen.getByRole('link')
    fireEvent.click(card)

    // MemoryRouter navigates by changing location — verify the link behavior
    expect(card).toHaveAttribute('tabIndex', '0')
  })
})

// ---------------------------------------------------------------------------
// Tests: Pickup day indicator
// ---------------------------------------------------------------------------

describe('RepairCard — pickup day indicator', () => {
  it('shows pickup indicator when pickupDate is set', () => {
    const repair = createRepair({ pickupDate: 1706918400000 }) // Feb 3, 2024
    render(
      <MemoryRouter>
        <RepairCard repair={repair} workers={[]} />
      </MemoryRouter>
    )
    expect(screen.getByText(/pickup/i)).toBeInTheDocument()
  })

  it('does not show pickup indicator when pickupDate is null', () => {
    renderCard(createRepair({ pickupDate: null }))
    expect(screen.queryByText(/pickup/i)).not.toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: customerName fallback
// ---------------------------------------------------------------------------

describe('RepairCard — customer name fallback', () => {
  it('renders "—" when customerName is null', () => {
    renderCard(createRepair({ customerName: null }))
    expect(screen.getByText('—')).toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: Reschedule popover trigger
// ---------------------------------------------------------------------------

describe('RepairCard — reschedule', () => {
  it('renders a calendar icon button to open reschedule popover', () => {
    render(
      <MemoryRouter>
        <RepairCard repair={createRepair()} workers={[]} onReschedule={() => {}} />
      </MemoryRouter>,
    )
    // The card should have buttons (reschedule icon)
    const buttons = screen.getAllByRole('button')
    expect(buttons.length).toBeGreaterThan(0)
  })

  it('opens reschedule popover when calendar icon is clicked', () => {
    render(
      <MemoryRouter>
        <RepairCard repair={createRepair()} workers={[]} onReschedule={() => {}} />
      </MemoryRouter>,
    )
    const buttons = screen.getAllByRole('button')
    // Click the reschedule button (last button in card)
    fireEvent.click(buttons[buttons.length - 1])

    // Popover should be visible — check for date input
    expect(document.querySelector('input[type="date"]')).toBeInTheDocument()
  })

  it('closes popover when cancel is clicked', () => {
    render(
      <MemoryRouter>
        <RepairCard repair={createRepair()} workers={[]} onReschedule={() => {}} />
      </MemoryRouter>,
    )
    const buttons = screen.getAllByRole('button')
    fireEvent.click(buttons[buttons.length - 1]) // Open popover

    expect(document.querySelector('input[type="date"]')).toBeInTheDocument()

    // Click cancel
    fireEvent.click(screen.getByText(/cancel/i))

    expect(document.querySelector('input[type="date"]')).not.toBeInTheDocument()
  })

  it('clicking reschedule icon does not navigate to detail page', () => {
    render(
      <MemoryRouter initialEntries={['/repairs']}>
        <RepairCard repair={createRepair()} workers={[]} onReschedule={() => {}} />
      </MemoryRouter>,
    )
    const buttons = screen.getAllByRole('button')
    fireEvent.click(buttons[buttons.length - 1]) // Click reschedule icon

    // Should not have navigated — popover should be open instead
    expect(document.querySelector('input[type="date"]')).toBeInTheDocument()
  })
})

